arguments.file_text:
@using sv_d61bb45c3ba1482388fff42da68241c0.Services

<div class="channel-sidebar">
    <div class="sidebar-header">
        <h3>Channels</h3>
    </div>
    <div class="channel-list">
        @foreach (var channel in Channels)
        {
            <ChannelItem Channel="channel"
                         IsActive="channel.Id == ActiveChannelId"
                         OnSelected="OnChannelSelected" />
        }
    </div>
</div>

@code {
    [Parameter, EditorRequired] public List<Channel> Channels { get; set; } = [];
    [Parameter] public int? ActiveChannelId { get; set; }
    [Parameter] public EventCallback<int> OnChannelSelected { get; set; }
}

.channel-sidebar {
    width: 240px;
    min-width: 240px;
    background-color: #2b2d31;
    display: flex;
    flex-direction: column;
    border-right: 1px solid #1e1f22;
    height: 100%;
    overflow: hidden;
}

.sidebar-header {
    padding: 16px 12px 12px;
    border-bottom: 1px solid #1e1f22;
}

.sidebar-header h3 {
    margin: 0;
    font-size: 1rem;
    font-weight: 700;
    color: #f2f3f5;
    text-transform: uppercase;
    letter-spacing: 0.04em;
}

.channel-list {
    flex: 1;
    overflow-y: auto;
    padding: 8px 0;
}

.channel-list::-webkit-scrollbar {
    width: 4px;
}

.channel-list::-webkit-scrollbar-thumb {
    background-color: #1e1f22;
    border-radius: 2px;
}

@using sv_d61bb45c3ba1482388fff42da68241c0.Services

<div class="thread-panel">
    <div class="thread-header">
        <h4>Thread</h4>
        <button class="close-btn" @onclick="OnClose" title="Close thread">✕</button>
    </div>

    @if (RootMessage is not null)
    {
        <div class="thread-root-message">
            <span class="root-author">@RootMessage.Author</span>
            <p class="root-content">@RootMessage.Content</p>
        </div>

        <div class="thread-divider">
