@page "/chat"
@layout ChatLayout
@rendermode InteractiveServer
@using sv_d61bb45c3ba1482388fff42da68241c0.Services
@inject IChatService ChatService
@inject IJSRuntime JS
@implements IAsyncDisposable

<PageTitle>Chat</PageTitle>

<div class="chat-container">
    <ChannelSidebar Channels="channels"
                    ActiveChannelId="selectedChannelId"
                    OnChannelSelected="SelectChannel" />

    <div class="message-area @(isThreadOpen ? "" : "expanded")">
        @if (selectedChannel is not null)
        {
            <div class="area-header">
                <h3># @selectedChannel.Name</h3>
                <p>@selectedChannel.Description</p>
            </div>

            <div class="message-list" @ref="messageListRef">
                @if (hasMoreMessages)
                {
                    <div @ref="scrollSentinelRef" class="load-more-sentinel">
                        @if (isLoadingMore)
                        {
                            <span class="loading-text">Loading older messages…</span>
                        }
                    </div>
                }

                @foreach (var msg in messages)
                {
                    <MessageItem Message="msg"
                                 ThreadSummary="GetThreadSummary(msg.Id)"
                                 OnOpenThread="OpenThread"
                                 OnReact="HandleReaction" />
                }
            </div>

            <MessageInput Placeholder="@($"Message #{selectedChannel.Name}")"
                          ButtonText="Send"
                          OnSubmit="SendMessage" />
        }
        else
        {
            <div class="no-channel-selected">
                <p>Select a channel to start chatting</p>
            </div>
        }
    </div>

    @if (isThreadOpen)
    {
        <ThreadPanel RootMessage="threadRootMessage"
                     Replies="threadReplies"
                     OnClose="CloseThread"
                     OnReply="SendThreadReply" />
    }
</div>

@code {
    private List<Channel> channels = [];
    private Channel? selectedChannel;
    private int? selectedChannelId;
    private List<Message> messages = [];
    private Dictionary<int, ThreadSummary> threadSummaries = new();

    private bool isThreadOpen;
    private Message? threadRootMessage;
    private int? activeThreadRootId;
    private List<Message> threadReplies = [];

    private bool hasMoreMessages = true;
    private bool isLoadingMore;
    private const int PageSize = 50;

    private ElementReference messageListRef;
    private ElementReference scrollSentinelRef;
    private IJSObjectReference? jsModule;
    private DotNetObjectReference<ChatPage>? dotNetRef;
    private bool shouldScrollToBottom;
    private bool needsObserverInit;

    protected override async Task OnInitializedAsync()
    {
        channels = await ChatService.GetChannelsAsync();
        if (channels.Count > 0)
        {
            await SelectChannel(channels[0].Id);
        }
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            jsModule = await JS.InvokeAsync<IJSObjectReference>("import", "./js/chat.js");
            dotNetRef = DotNetObjectReference.Create(this);
        }

        if (needsObserverInit)
        {
            needsObserverInit = false;
            await SetupScrollObserver();
        }

        if (shouldScrollToBottom && jsModule is not null)
        {
            shouldScrollToBottom = false;
            await jsModule.InvokeVoidAsync("scrollToBottom", messageListRef);
        }
    }

    private async Task SetupScrollObserver()
    {
        if (jsModule is not null && dotNetRef is not null && hasMoreMessages)
        {
            await jsModule.InvokeVoidAsync("initScrollObserver", scrollSentinelRef, dotNetRef);
        }
    }

    private async Task SelectChannel(int channelId)
    {
        if (selectedChannelId == channelId) return;

        selectedChannelId = channelId;
        selectedChannel = channels.FirstOrDefault(c => c.Id == channelId);
        messages = [];
        threadSummaries.Clear();
        hasMoreMessages = true;
        isLoadingMore = false;
        CloseThreadInternal();

        var loaded = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
        messages = loaded;
        hasMoreMessages = loaded.Count >= PageSize;
        BuildThreadSummaries();

        shouldScrollToBottom = true;
        needsObserverInit = true;

        await ChatService.MarkChannelReadAsync(channelId);
        channels = await ChatService.GetChannelsAsync();
    }

    [JSInvokable]
    public async Task OnScrolledToTop()
    {
        if (isLoadingMore || !hasMoreMessages || selectedChannelId is null) return;

        isLoadingMore = true;
        StateHasChanged();

        var previousScrollHeight = 0;
        if (jsModule is not null)
        {
            previousScrollHeight = await jsModule.InvokeAsync<int>("getScrollHeight", messageListRef);
        }

        var older = await ChatService.GetMessagesAsync(selectedChannelId.Value, messages.Count, PageSize);

        if (older.Count > 0)
        {
            messages.InsertRange(0, older);
            BuildThreadSummaries();
        }

        hasMoreMessages = older.Count >= PageSize;
        isLoadingMore = false;
        StateHasChanged();

        if (jsModule is not null && previousScrollHeight > 0)
        {
            await jsModule.InvokeVoidAsync("maintainScrollPosition", messageListRef, previousScrollHeight);
        }

        if (hasMoreMessages)
        {
            needsObserverInit = true;
        }
    }

    private async Task SendMessage(string content)
    {
        if (selectedChannelId is null) return;
        var message = await ChatService.SendMessageAsync(selectedChannelId.Value, content, null);
        messages.Add(message);
        shouldScrollToBottom = true;
    }

    private async Task OpenThread(int messageId)
    {
        threadRootMessage = messages.FirstOrDefault(m => m.Id == messageId);
        if (threadRootMessage is null) return;

        activeThreadRootId = messageId;
        threadReplies = await ChatService.GetThreadAsync(messageId);
        isThreadOpen = true;
    }

    private void CloseThread() => CloseThreadInternal();

    private void CloseThreadInternal()
    {
        isThreadOpen = false;
        threadRootMessage = null;
        activeThreadRootId = null;
        threadReplies = [];
    }

    private async Task SendThreadReply(string content)
    {
        if (selectedChannelId is null || activeThreadRootId is null) return;

        var reply = await ChatService.SendMessageAsync(selectedChannelId.Value, content, activeThreadRootId);
        threadReplies.Add(reply);
        BuildThreadSummaries();
    }

    private async Task HandleReaction((int MessageId, string Emoji) reaction)
    {
        await ChatService.AddReactionAsync(reaction.MessageId, reaction.Emoji);

        if (selectedChannelId is not null)
        {
            var refreshed = await ChatService.GetMessagesAsync(selectedChannelId.Value, 0, messages.Count);
            messages = refreshed;
            BuildThreadSummaries();
        }
    }

    private void BuildThreadSummaries()
    {
        threadSummaries.Clear();
        var replies = messages.Where(m => m.ReplyToId is not null);
        foreach (var group in replies.GroupBy(m => m.ReplyToId!.Value))
        {
            threadSummaries[group.Key] = new ThreadSummary(
                group.Key,
                group.Count(),
                group.Max(m => m.SentAt));
        }
    }

    private ThreadSummary? GetThreadSummary(int messageId) =>
        threadSummaries.GetValueOrDefault(messageId);

    public async ValueTask DisposeAsync()
    {
        if (jsModule is not null)
        {
            try
            {
                await jsModule.InvokeVoidAsync("disposeScrollObserver");
                await jsModule.DisposeAsync();
            }
            catch (JSDisconnectedException)
            {
                // Circuit may already be gone
            }
        }
        dotNetRef?.Dispose();
    }
}

.chat-container {
    display: flex;
    height: 100vh;
    width: 100%;
    background-color: #313338;
    color: #dcddde;
    font-family: 'Segoe UI', 'Helvetica Neue', Arial, sans-serif;
}

/* Main message area — flexes to fill remaining space */
.message-area {
    flex: 1;
