    font-weight: 700;
    color: #f2f3f5;
}

.area-header p {
    margin: 4px 0 0;
    font-size: 0.82rem;
    color: #8e9297;
}

.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 8px 0;
}

.message-list::-webkit-scrollbar {
    width: 6px;
}

