    background-color: #1e1f22;
    border-radius: 3px;
}

.load-more-sentinel {
    text-align: center;
    padding: 8px;
    min-height: 1px;
}

.loading-text {
    font-size: 0.8rem;
    color: #72767d;
}

.no-channel-selected {
    flex: 1;
    display: flex;
    align-items: center;
    justify-content: center;
}

.no-channel-selected p {
